function validate([count, upgrade, sell, money]) {
  const n = count.length;
  if (n < 1 || n > 100000) return 'There must be 1 to 10^5 data centers.';
  if (upgrade.length !== n || sell.length !== n || money.length !== n) return 'All four arrays must have the same length.';
  for (const arr of [count, upgrade, sell, money]) {
    if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Every value is an integer from 1 to 10^5.';
  }
  return null;
}

