function maxUpgrades(count, upgrade, sell, money) {
  const answer = [];

  for (let i = 0; i < count.length; i++) {
    const budget = money[i] + count[i] * sell[i];
    const pricePerUpgrade = upgrade[i] + sell[i];
    const affordable = Math.floor(budget / pricePerUpgrade);
    answer.push(Math.min(count[i], affordable));
  }
  return answer;
}

