function maxUpgrades(count, upgrade, sell, money) {
  // Try every number of upgrades from the most to the fewest; sell all the others.
  return count.map((servers, i) => {
    for (let kept = servers; kept >= 0; kept--) {
      const cash = money[i] + (servers - kept) * sell[i];
      if (kept * upgrade[i] <= cash) return kept;
    }
    return 0;
  });
}

