function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 5);
  const count = [], upgrade = [], sell = [], money = [];
  for (let i = 0; i < n; i++) {
    const top = size === 'large' ? (rand() < 0.5 ? 100000 : pick(1, 1000)) : (rand() < 0.15 ? 100000 : pick(1, 12));
    count.push(size === 'large' ? pick(1, 100000) : pick(1, 12));
    upgrade.push(pick(1, top));
    sell.push(pick(1, top));
    money.push(pick(1, top));
  }
  return [count, upgrade, sell, money];
}
